const bits = {
  directFire: 1,
  artemis: 2,
  riscLaser: 4,
  apollo: 8,
  infantry: 16,
} as const;

function unpack(data: string): ReadonlyMap<string, number> {
  return new Map(
    data.split(' ').map((item) => {
      const [id, value] = item.split(':');
      return [id, Number(value)] as const;
    }),
  );
}

export function hasNativeWeaponBVFlag(
  id: string,
  flag: keyof typeof bits,
): boolean | undefined {
  const [ids, names] =
    flag === 'infantry'
      ? [infantryCanonical, infantryNative]
      : [canonical, native];
  const value =
    ids.get(id) ?? names.get(id.toLowerCase().replace(/[^a-z0-9]/g, ''));
  return value === undefined ? undefined : (value & bits[flag]) !== 0;
}
